public class Ex06ConditionalOnProperty {
    static boolean matches(String value, String havingValue, boolean matchIfMissing) {
        if (value == null) return matchIfMissing;
        if (havingValue == null || havingValue.isEmpty()) {
            // 未指定 havingValue 时：只要不是 "false" 即算匹配
            return !"false".equalsIgnoreCase(value);
        }
        return havingValue.equals(value);
    }

    public static void main(String[] args) {
        System.out.println("enabled=true,  havingValue=\"\"     -> " + matches("true", "", false));
        System.out.println("enabled=false, havingValue=\"\"     -> " + matches("false", "", false));
        System.out.println("enabled=abc,   havingValue=\"\"     -> " + matches("abc", "", false));
        System.out.println("enabled=null,  matchIfMissing=false -> " + matches(null, "", false));
        System.out.println("enabled=null,  matchIfMissing=true  -> " + matches(null, "", true));
        System.out.println("mode=prod,     havingValue=prod     -> " + matches("prod", "prod", false));
        System.out.println("mode=dev,      havingValue=prod     -> " + matches("dev", "prod", false));
    }
}
